import { bootstrap, pair, consume, devices, secret } from "./v3/devices";
import { artifact, checkpointRead, checkpointPublish, gc, lease } from "./v3/history";
import { authorize } from "./v3/common";
import { aad, boundedJSON, ciphertext, counter, PAGE_SIZE, ProtocolError, sha256, uuid } from "./protocol";

// Env is generated by `npm run types` from cloudflare.config.ts.
type State = { id: string; epoch: string; head: number; gc_floor: number; maintenance: number;
  charged_bytes: number; byte_budget: number; batch_budget: number; log_count:number; log_bytes:number; checkpoint_id:string|null; recovery_from_epoch:string|null; recovery_head:number|null; recovery_floor:number|null; key_check:string|null; checkpoint_covered:number; device_id: string | null };
type Receipt = { batch_id: string; revision: number; digest: string; device_id: string };
type Commit = Receipt & { ciphertext: string; artifact_ids:string };
type Auth = { vaultID: string; tokenHash: string };
const encoder = new TextEncoder();

export function json(body: unknown, status = 200): Response {
  return Response.json(body, { status, headers: { "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff" } });
}
function stateQuery(db: D1Database, auth: Auth): D1PreparedStatement {
  return db.prepare(`SELECT v.*,COALESCE((SELECT covered FROM checkpoints WHERE vault_id=v.id AND epoch=v.epoch AND id=v.checkpoint_id),0) AS checkpoint_covered, d.id AS device_id FROM vaults v
    LEFT JOIN devices d ON d.vault_id=v.id AND d.token_hash=? AND d.revoked_at IS NULL
    WHERE v.id=?`).bind(auth.tokenHash, auth.vaultID);
}
function check(state: State | undefined, epoch?: string): State {
  if (!state?.device_id) throw new ProtocolError("authentication_required", 401);
  if (state.maintenance) throw new ProtocolError("maintenance", 503);
  if (epoch !== undefined && state.epoch !== epoch) throw new ProtocolError("epoch_mismatch", 409);
  return state;
}
function usage(results: D1Result<unknown>[], route: string): void {
  console.log(JSON.stringify({ event: "d1_usage", route,
    rows_read: results.reduce((n, r) => n + r.meta.rows_read, 0),
    rows_written: results.reduce((n, r) => n + r.meta.rows_written, 0) }));
}
function receiptBody(env: Env, state: State, receipt: Receipt) {
  // Upload confirmation carries no pull cursor or local-application acknowledgement.
  return { version: 3, serviceID: env.SERVICE_ID, vaultID: state.id, epoch: state.epoch,
    receipt: { batchID: receipt.batch_id, revision: receipt.revision, digest: receipt.digest } };
}
export async function appendBatch(request: Request, env: Env, auth: Auth): Promise<Response> {
  const body = await boundedJSON(request);
  if (body.version !== 3) throw new ProtocolError("unsupported_version", 426);
  if (Object.keys(body).some(k => !["version", "epoch", "batchID", "ciphertext", "artifactIDs"].includes(k))) throw new ProtocolError("invalid_request", 400);
  const epoch = uuid(body.epoch), batchID = uuid(body.batchID);
  const refs=Array.isArray(body.artifactIDs)?body.artifactIDs as string[]:[];
  if(body.artifactIDs!==undefined&&!Array.isArray(body.artifactIDs))throw new ProtocolError("invalid_request",400);
  if(refs.length>512||refs.some((x,i)=>typeof x!=="string"||!(/^[a-f0-9]{64}$/.test(x))||(i>0&&refs[i-1]>=x)))throw new ProtocolError("invalid_request",400);
  const sealed = ciphertext(body.ciphertext);
  const associated = aad(env.SERVICE_ID, auth.vaultID, epoch, "batch", batchID,refs);
  const bound = new Uint8Array(associated.length + 1 + sealed.length);
  bound.set(associated); bound[associated.length] = 0; bound.set(sealed, associated.length + 1);
  const digest = await sha256(bound), charge = (body.ciphertext as string).length + 2048;
  const db = env.DB;
  // No RETURNING values are dynamically rebound. Every statement selects the
  // previous step's row by its immutable identity, inside one SQLite transaction.
  const results = await db.batch([
    db.prepare(`INSERT INTO commits(vault_id,epoch,revision,batch_id,device_id,digest,ciphertext,created_at,artifact_ids,log_charge,replay_bytes)
      SELECT v.id,v.epoch,v.head+1,?,d.id,?,?,?,?,?,?+COALESCE((SELECT SUM(bytes) FROM artifacts WHERE vault_id=v.id AND epoch=v.epoch AND digest IN (SELECT value FROM json_each(?))),0) FROM vaults v
      JOIN devices d ON d.vault_id=v.id AND d.token_hash=? AND d.revoked_at IS NULL
      WHERE v.id=? AND v.epoch=? AND v.maintenance=0 AND v.log_count<v.batch_budget
        AND v.head<9007199254740991 AND v.charged_bytes<=v.byte_budget-?
        AND (v.recovery_from_epoch IS NULL OR v.checkpoint_id IS NOT NULL)
        AND (SELECT COUNT(*) FROM artifacts x WHERE x.vault_id=v.id AND x.epoch=v.epoch AND x.digest IN (SELECT value FROM json_each(?)))=?
        AND NOT EXISTS(SELECT 1 FROM receipts r WHERE r.vault_id=v.id AND r.epoch=v.epoch AND r.batch_id=?)`)
      .bind(batchID, digest, body.ciphertext as string, Date.now(),JSON.stringify(refs),charge-1024,charge-1024,JSON.stringify(refs), auth.tokenHash, auth.vaultID, epoch, charge,JSON.stringify(refs),refs.length, batchID),
    db.prepare(`INSERT INTO receipts(vault_id,epoch,batch_id,revision,device_id,digest)
      SELECT vault_id,epoch,batch_id,revision,device_id,digest FROM commits c
      WHERE c.vault_id=? AND c.epoch=? AND c.batch_id=? AND c.digest=?
        AND NOT EXISTS(SELECT 1 FROM receipts r WHERE r.vault_id=c.vault_id AND r.epoch=c.epoch AND r.batch_id=c.batch_id)`)
      .bind(auth.vaultID, epoch, batchID, digest),
    db.prepare(`UPDATE vaults SET head=head+1,charged_bytes=charged_bytes+?,log_count=log_count+1,log_bytes=log_bytes+COALESCE((SELECT replay_bytes FROM commits c WHERE c.vault_id=vaults.id AND c.epoch=vaults.epoch AND c.batch_id=?),0)
      WHERE id=? AND epoch=? AND EXISTS(SELECT 1 FROM commits c
        WHERE c.vault_id=vaults.id AND c.epoch=vaults.epoch AND c.batch_id=? AND c.digest=? AND c.revision=vaults.head+1)`)
      .bind(charge,batchID, auth.vaultID, epoch, batchID, digest),
    db.prepare(`INSERT INTO commit_artifacts(vault_id,epoch,revision,digest) SELECT c.vault_id,c.epoch,c.revision,j.value FROM commits c,json_each(c.artifact_ids) j WHERE c.vault_id=? AND c.epoch=? AND c.batch_id=? AND NOT EXISTS(SELECT 1 FROM commit_artifacts r WHERE r.vault_id=c.vault_id AND r.epoch=c.epoch AND r.revision=c.revision AND r.digest=j.value)`).bind(auth.vaultID,epoch,batchID),
    stateQuery(db, auth),
    db.prepare(`SELECT batch_id,revision,digest,device_id FROM receipts WHERE vault_id=? AND epoch=? AND batch_id=?`)
      .bind(auth.vaultID, epoch, batchID)
  ]);
  usage(results, "push");
  const state = check(results[4].results[0] as State | undefined, epoch);
  const receipt = results[5].results[0] as Receipt | undefined;
  if (!receipt) {
    if(state.recovery_from_epoch)throw new ProtocolError("checkpoint_required",409);
    const found=await db.prepare("SELECT COUNT(*) AS n FROM artifacts WHERE vault_id=? AND epoch=? AND digest IN (SELECT value FROM json_each(?))").bind(auth.vaultID,epoch,JSON.stringify(refs)).first<{n:number}>();
    if(found?.n!==refs.length)throw new ProtocolError("artifact_missing",409);
    throw new ProtocolError("quota_unavailable",503);
  }
  if (receipt.digest !== digest) throw new ProtocolError("batch_conflict", 409);
  return json(receiptBody(env, state, receipt));
}
async function pull(url: URL, env: Env, auth: Auth): Promise<Response> {
  const epoch = uuid(url.searchParams.get("epoch")), after = counter(url.searchParams.get("after"));
  // Metadata and page are read in one batch on the primary, including a fresh
  // authorization check. A future GC transaction cannot split this snapshot.
  const results = await env.DB.batch([
    stateQuery(env.DB, auth),
    env.DB.prepare(`SELECT c.batch_id,c.revision,c.digest,c.device_id,c.ciphertext,c.artifact_ids FROM commits c
      JOIN vaults v ON v.id=c.vault_id
      JOIN devices d ON d.vault_id=v.id AND d.token_hash=? AND d.revoked_at IS NULL
      WHERE c.vault_id=? AND c.epoch=? AND c.revision>? AND v.maintenance=0
        AND (v.epoch=c.epoch OR EXISTS(SELECT 1 FROM leases l WHERE l.id=? AND l.vault_id=v.id AND l.epoch=c.epoch AND l.device_id=d.id AND l.expires_at>?))
      ORDER BY c.revision LIMIT ?`).bind(auth.tokenHash, auth.vaultID, epoch, after,url.searchParams.get("lease")??"",Date.now(), PAGE_SIZE)
  ]);
  usage(results, "pull");
  const state = check(results[0].results[0] as State | undefined);
  let floor=state.gc_floor,head=state.head;
  if(state.epoch!==epoch){
    if(state.recovery_from_epoch!==epoch)throw new ProtocolError("epoch_mismatch",409);
    head=state.recovery_head??0;floor=state.recovery_floor??0;
  }
  if (after < floor) throw new ProtocolError("checkpoint_required", 409);
  if (after > head) throw new ProtocolError("cursor_mismatch", 409);
  const commits = results[1].results as Commit[];
  if (commits.some((c, i) => c.revision !== after + i + 1) || (!commits.length && after < head)) throw new ProtocolError("corrupt_data", 503);
  const nextCursor = commits.at(-1)?.revision ?? after;
  return json({ version: 3, serviceID: env.SERVICE_ID, vaultID: state.id, epoch,
    head, gcFloor: floor, nextCursor, hasMore: nextCursor < head,
    commits: commits.map(c => ({ batchID: c.batch_id, revision: c.revision, digest: c.digest, ciphertext: c.ciphertext,artifactIDs:JSON.parse(c.artifact_ids) })) });
}
async function route(request: Request, env: Env): Promise<Response> {
  // Release gate: P2/P4/P5 are required before any production activation.
  if (env.LOG_CORE_ENABLED !== "development-only" && env.SYNC_ENABLED !== "true") throw new ProtocolError("maintenance", 503);
  uuid(env.SERVICE_ID);
  const url = new URL(request.url);
  if(url.pathname==="/v3/bootstrap"&&request.method==="POST")return bootstrap(request,env);
  if(url.pathname.startsWith("/v3/admin/")&&request.method==="POST"){
    await secret(request,env.RECOVERY_SECRET);const b=await boundedJSON(request);const vault=uuid(b.vaultID);
    if(url.pathname.endsWith("/maintenance")){await env.DB.prepare("UPDATE vaults SET maintenance=? WHERE id=?").bind(b.enabled===true?1:0,vault).run();return json({maintenance:b.enabled===true});}
    if(url.pathname.endsWith("/recover")){const epoch=uuid(b.epoch);const r=await env.DB.prepare("UPDATE vaults SET recovery_from_epoch=epoch,recovery_head=head,recovery_floor=gc_floor,epoch=?,head=0,gc_floor=0,checkpoint_id=NULL,log_count=0,log_bytes=0,maintenance=0 WHERE id=? AND maintenance=1 AND epoch!=? AND recovery_from_epoch IS NULL").bind(epoch,vault,epoch).run();if(!r.meta.changes)throw new ProtocolError("epoch_mismatch",409);return json({epoch});}
    throw new ProtocolError("not_found",404);
  }
  const consumed=/^\/v3\/vaults\/([^/]+)\/pairings\/([^/]+)\/consume$/.exec(url.pathname);
  if(consumed&&request.method==="POST")return consume(request,env,uuid(consumed[1]),uuid(consumed[2]));
  if (request.method === "GET" && ["/", "/health"].includes(url.pathname)) {
    const results = await env.DB.batch([
      env.DB.prepare("SELECT id FROM vaults LIMIT 0"),
      env.DB.prepare("SELECT id FROM devices LIMIT 0"),
      env.DB.prepare("SELECT vault_id FROM commits LIMIT 0"),
      env.DB.prepare("SELECT vault_id FROM receipts LIMIT 0")
    ]);
    usage(results, "health");
    return json({ service: "pindo-sync", version: 3, status: "ok", serviceID: env.SERVICE_ID,
      capabilities: env.SYNC_ENABLED==="true"?["v3-sync","pairing","artifacts","checkpoints","gc"]:["development-log-core"], clientSyncAvailable: env.SYNC_ENABLED==="true" });
  }
  const match = /^\/v3\/vaults\/([^/]+)\/(info|push|pull|receipts\/([^/]+)|pairings|devices(?:\/[^/]+\/(?:rotate|revoke))?|artifacts\/[^/]+|checkpoints|leases\/[^/]+|gc)$/.exec(url.pathname);
  if (!match) throw new ProtocolError("not_found", 404);
  const vaultID = uuid(match[1]);
  const header = request.headers.get("Authorization");
  if (!header || !/^Bearer [A-Za-z0-9_-]{43}$/.test(header)) throw new ProtocolError("authentication_required", 401);
  const auth = { vaultID, tokenHash: await sha256(encoder.encode(header.slice(7))) };
  const preflight = await env.DB.batch([stateQuery(env.DB, auth)]);
  usage(preflight, "authenticate");
  const state = check(preflight[0].results[0] as State | undefined);
  if(match[2]==="pairings"&&request.method==="POST")return pair(request,env,auth);
  if(match[2].startsWith("devices"))return devices(request,env,auth,match[2]);
  if(match[2].startsWith("artifacts/"))return artifact(request,env,auth,match[2],url);
  if(match[2].startsWith("leases/"))return lease(request,env,auth,match[2].split("/")[1]);
  if(match[2]==="checkpoints")return request.method==="GET"?checkpointRead(env,auth,url):checkpointPublish(request,env,auth);
  if(match[2]==="gc"&&request.method==="POST"){const b=await boundedJSON(request);return gc(env,auth,uuid(b.epoch));}
  if (match[2] === "push" && request.method === "POST") return appendBatch(request, env, auth);
  if (request.method !== "GET") throw new ProtocolError("invalid_request", 405);
  if (match[2] === "info") return json({ version: 3, serviceID: env.SERVICE_ID, vaultID, epoch: state.epoch,
    head: state.head, gcFloor: state.gc_floor,checkpointID:state.checkpoint_id,checkpointCovered:state.checkpoint_covered,logCount:state.log_count,logBytes:state.log_bytes,recoveryFromEpoch:state.recovery_from_epoch,recoveryHead:state.recovery_head,recoveryFloor:state.recovery_floor,keyCheck:state.key_check?JSON.parse(state.key_check):null, capabilities: ["v3-sync","pairing","artifacts","checkpoints","gc"] });
  if (match[2] === "pull") return pull(url, env, auth);
  const batchID = uuid(match[3]), epoch = uuid(url.searchParams.get("epoch"));
  const results = await env.DB.batch([stateQuery(env.DB, auth),
    env.DB.prepare(`SELECT batch_id,revision,digest,device_id FROM receipts WHERE vault_id=? AND epoch=? AND batch_id=?`)
      .bind(vaultID, epoch, batchID)]);
  usage(results, "receipt");
  const current = check(results[0].results[0] as State | undefined, epoch);
  const receipt = results[1].results[0] as Receipt | undefined;
  if (!receipt) throw new ProtocolError("not_found", 404);
  return json(receiptBody(env, current, receipt));
}
export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    try { return await route(request, env); }
    catch (error) {
      if (error instanceof ProtocolError) return json({ version: 3, error: { code: error.code } }, error.status);
      // Do not echo SQL, tokens, ciphertext or server exception bodies.
      console.error(JSON.stringify({ event: "storage_failure" }));
      return json({ version: 3, error: { code: "storage_unavailable" } }, 503);
    }
  }
} satisfies ExportedHandler<Env>;
